import json,os,resource,subprocess,sys
from pathlib import Path
resource.setrlimit(resource.RLIMIT_AS,(268435456,resource.RLIM_INFINITY));resource.setrlimit(resource.RLIMIT_CPU,(10,10));os.sched_setaffinity(0,{min(os.sched_getaffinity(0))})
